// Lote 1a, herramienta 9: the geofence editor logic of the flight simulator, a line-by-line port of src/shared/geofence.ts. Pure C# (no UnityEngine), so the
// EditMode golden test (contracts/golden/geofence.json, generated by the web's own code) runs it directly.
//
// The geofence belongs to the SIMULATOR only (SimState.cfg): it is local state of the model and never travels on the wire. The fence of PX4 (GF_*) does
// not reach the client, so nothing here applies to SITL or to the replay. Every value it produces is simulated.
//
// Frames: the position is the local NED of TelemetryFrame.p (p[0] north, p[1] east, p[2] down), metres, relative to the take-off point.

using System;
using System.Collections.Generic;
using System.Globalization;
using WebGL.Telemetry.Json;

namespace WebGL.Telemetry
{
    /// <summary>Geofence of the simulator: horizontal radius around the take-off point, ceiling above it and the altitude RTL climbs to, all in metres.</summary>
    public class FenceConfig
    {
        public double radius = 120, ceiling = 60, rtlAltitude = 10;

        public FenceConfig() { }
        public FenceConfig(double radius, double ceiling, double rtlAltitude) { this.radius = radius; this.ceiling = ceiling; this.rtlAltitude = rtlAltitude; }
        public FenceConfig CloneFence() => new FenceConfig(radius, ceiling, rtlAltitude);
    }

    /// <summary>The verdict of a validation: ok, or a stable code (with its range) and the Spanish reason of the first thing refused.</summary>
    public struct ConfigCheck
    {
        public bool ok;
        public string code;
        public string detail;
        public double? min, max;

        public static readonly ConfigCheck Ok = new ConfigCheck { ok = true };
        public static ConfigCheck No(string code, string detail, double? min = null, double? max = null) => new ConfigCheck { ok = false, code = code, detail = detail, min = min, max = max };
    }

    public enum FenceStatus { Ok, Near, Hit }

    public static class Geofence
    {
        /// <summary>Ranges and in-flight margins of the editor. 120 m of ceiling is the usual open-category limit, informational only.</summary>
        public const double RadiusMin = 20, RadiusMax = 200, RadiusStep = 5;
        public const double CeilingMin = 5, CeilingMax = 120, CeilingStep = 1;
        /// <summary>In flight the new radius must clear the current horizontal distance by this much, m.</summary>
        public const double RadiusMargin = 5;
        /// <summary>In flight the new ceiling must clear the current height by this much, m.</summary>
        public const double CeilingMargin = 2;
        /// <summary>Lowest RTL altitude (the simulator never climbs lower than 1 m).</summary>
        public const double RtlMin = 1;
        /// <summary>The vehicle is "near" a wall when it is closer than this, m: the ring turns amber.</summary>
        public const double NearM = 5;
        /// <summary>... and "at" the wall (the model pins it there) within this distance, m: the ring turns red.</summary>
        public const double HitM = 0.05;

        const double Eps = 1e-9;

        public static FenceConfig Default() => new FenceConfig(120, 60, 10);

        /// <summary>JS String(Math.round(x * 10) / 10): "50", "10.5".</summary>
        static string Num(double x) => (JsMath.Round(x * 10) / 10).ToString("R", CultureInfo.InvariantCulture);

        static bool Finite(double x) => !double.IsNaN(x) && !double.IsInfinity(x);

        /// <summary>
        /// Checks a proposed geofence. On the ground only the ranges apply; in flight (armed and not landed) the new radius must be at least the current
        /// horizontal distance plus 5 m and the new ceiling at least the height plus 2 m: the vehicle is never teleported, the change is refused instead.
        /// `detail` is Spanish, like the acks of the simulator; `code` (with min / max) is what a UI translates.
        /// </summary>
        public static ConfigCheck Validate(FenceConfig cfg, double[] p, bool armed, bool landed)
        {
            double radius = cfg.radius, ceiling = cfg.ceiling, rtl = cfg.rtlAltitude;
            if (!Finite(radius) || !Finite(ceiling) || !Finite(rtl)) return ConfigCheck.No("not_finite", "valores no válidos");
            if (radius < RadiusMin - Eps || radius > RadiusMax + Eps)
                return ConfigCheck.No("radius_range", "el radio debe estar entre " + Num(RadiusMin) + " y " + Num(RadiusMax) + " m", RadiusMin, RadiusMax);
            if (Math.Abs(radius / RadiusStep - JsMath.Round(radius / RadiusStep)) > Eps)
                return ConfigCheck.No("radius_step", "el radio va de " + Num(RadiusStep) + " en " + Num(RadiusStep) + " m", RadiusStep);
            if (ceiling < CeilingMin - Eps || ceiling > CeilingMax + Eps)
                return ConfigCheck.No("ceiling_range", "el techo debe estar entre " + Num(CeilingMin) + " y " + Num(CeilingMax) + " m", CeilingMin, CeilingMax);
            if (Math.Abs(ceiling / CeilingStep - JsMath.Round(ceiling / CeilingStep)) > Eps)
                return ConfigCheck.No("ceiling_step", "el techo va de " + Num(CeilingStep) + " en " + Num(CeilingStep) + " m", CeilingStep);
            if (rtl < RtlMin - Eps)
                return ConfigCheck.No("rtl_range", "la altura de RTL no puede ser menor que " + Num(RtlMin) + " m", RtlMin);
            if (rtl > ceiling + Eps)
                return ConfigCheck.No("rtl_above_ceiling", "la altura de RTL (" + Num(rtl) + " m) no puede superar el techo (" + Num(ceiling) + " m)", null, ceiling);
            if (armed && !landed)
            {
                double dist = Math.Sqrt(p[0] * p[0] + p[1] * p[1]);
                double alt = -p[2];
                if (radius + Eps < dist + RadiusMargin)
                {
                    double min = Math.Ceiling((dist + RadiusMargin - Eps) / RadiusStep) * RadiusStep;
                    return ConfigCheck.No("radius_below_position", "en vuelo, el radio debe superar en " + Num(RadiusMargin) + " m la distancia actual (" + Num(dist) + " m): mínimo " + Num(min) + " m", min);
                }
                if (ceiling + Eps < alt + CeilingMargin)
                {
                    double min = Math.Ceiling(alt + CeilingMargin - Eps);
                    return ConfigCheck.No("ceiling_below_altitude", "en vuelo, el techo debe superar en " + Num(CeilingMargin) + " m la altura actual (" + Num(alt) + " m): mínimo " + Num(min) + " m", min);
                }
            }
            return ConfigCheck.Ok;
        }

        /// <summary>Distance from the vehicle to the wall and to the lid of the fence, m (negative = outside).</summary>
        public static void Margins(double radius, double ceiling, double[] p, out double horizontal, out double vertical, out double min)
        {
            horizontal = radius - Math.Sqrt(p[0] * p[0] + p[1] * p[1]);
            vertical = ceiling - -p[2];
            min = Math.Min(horizontal, vertical);
        }

        /// <summary>`Near` when closer than 5 m to the wall or the lid, `Hit` when touching it (the model pins the vehicle there).</summary>
        public static FenceStatus Status(double radius, double ceiling, double[] p)
        {
            Margins(radius, ceiling, p, out _, out _, out double m);
            if (m <= HitM) return FenceStatus.Hit;
            return m < NearM ? FenceStatus.Near : FenceStatus.Ok;
        }

        public static string StatusName(FenceStatus s) => s == FenceStatus.Hit ? "hit" : s == FenceStatus.Near ? "near" : "ok";

        /// <summary>Tolerant reader of what the app stores (`{ radius, ceiling, rtlAltitude }` as JSON): anything invalid falls back to the defaults.</summary>
        public static FenceConfig Parse(string raw)
        {
            try
            {
                if (raw != null && TelemetryJson.TryParse(raw, out object v, out _) && v is Dictionary<string, object> o)
                {
                    double N(string k) => o.TryGetValue(k, out object x) && x is double d ? d : double.NaN;
                    var cfg = new FenceConfig(N("radius"), N("ceiling"), N("rtlAltitude"));
                    if (Validate(cfg, new double[3], false, true).ok) return cfg;
                }
            }
            catch (Exception) { /* falls through to the defaults */ }
            return Default();
        }

        /// <summary>The JSON the app stores under Desk_SimFence.</summary>
        public static string ToJson(FenceConfig c) =>
            "{\"radius\":" + TelemetryJson.Num(c.radius) + ",\"ceiling\":" + TelemetryJson.Num(c.ceiling) + ",\"rtlAltitude\":" + TelemetryJson.Num(c.rtlAltitude) + "}";
    }
}
